CREATE TABLE IF NOT EXISTS "security_mobile_deferred_operations" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "approval_request_id" bigint NOT NULL UNIQUE,
    "operation_payload_json" jsonb NOT NULL,
    "expected_fingerprint" char(64) NOT NULL,
    "status" varchar(16) NOT NULL DEFAULT 'pending',
    "executed_at" timestamp without time zone NULL,
    "failure_reason" text NULL,
    "created_at" timestamp without time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "security_mobile_deferred_status" CHECK ("status" IN ('pending', 'executed', 'failed', 'cancelled')),
    CONSTRAINT "fk_security_mobile_deferred_request" FOREIGN KEY ("approval_request_id") REFERENCES "security_mobile_approval_requests" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "security_mobile_rate_limits" (
    "limit_key" char(64) NOT NULL,
    "bucket_started_at" timestamp without time zone NOT NULL,
    "attempt_count" integer NOT NULL DEFAULT 0,
    "expires_at" timestamp without time zone NOT NULL,
    PRIMARY KEY ("limit_key", "bucket_started_at"),
    CONSTRAINT "security_mobile_rate_limit_count" CHECK ("attempt_count" >= 0)
);

CREATE INDEX IF NOT EXISTS "idx_security_mobile_rate_limits_expiry"
ON "security_mobile_rate_limits" ("expires_at");
